#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TranscriptOrder {
    Oldest,
    Latest,
}

impl TranscriptOrder {
    fn as_str(self) -> &'static str {
        match self {
            Self::Oldest => "oldest",
            Self::Latest => "latest",
        }
    }
}

