    pub(crate) fn for_test_transcript_refresh()
    -> (Self, Receiver<(String, String, Option<String>, String)>) {
        let (discovery, _events, refreshes) = Self::for_test_transcript_refresh_with_events(None);
        (discovery, refreshes)
    }

    #[cfg(test)]
    pub(crate) fn for_test_transcript_refresh_with_events(
        connection_id: Option<&str>,
    ) -> (
        Self,
        mpsc::Sender<GatewayEvent>,
        Receiver<(String, String, Option<String>, String)>,
    ) {
        let (_status_sender, status_receiver) = mpsc::channel();
        let (event_sender, event_receiver) = mpsc::channel();
        let (command_sender, _command_receiver) = mpsc::channel();
        let (plugin_update_all_sender, _plugin_update_all_receiver) = mpsc::channel();
        let (http_sender, http_receiver) = mpsc::channel();
        let (project_tree_sender, _project_tree_receiver) = mpsc::channel();
        let (cron_trigger_sender, _cron_trigger_receiver) = mpsc::sync_channel(1);
        let (artifact_sender, _artifact_receiver) = mpsc::channel();
        let (artifact_download_sender, _artifact_download_receiver) = mpsc::channel();
        let (artifact_image_sender, _artifact_image_receiver) = mpsc::channel();
        let (refresh_sender, refresh_receiver) = mpsc::channel();
        thread::spawn(move || {
            while let Ok(command) = http_receiver.recv() {
                if let GatewayHttpCommand::RefreshActiveTranscript {
                    request_id,
                    session_id,
                    profile,
                    runtime_session_id,
                } = command
                    && refresh_sender
                        .send((request_id, session_id, profile, runtime_session_id))
                        .is_err()
                {
                    break;
                }
            }
        });
        (
            Self {
                status_receiver,
                event_receiver,
                connection_id: connection_id.map(str::to_owned),
                command_sender,
                plugin_update_all_sender,
                http_sender,
                project_tree_sender,
                cron_trigger_sender,
                artifact_sender,
                artifact_download_sender,
                artifact_image_sender,
            },
            event_sender,
            refresh_receiver,
        )
    }

    pub fn start() -> Self {
        let mut start_pending = true;
        let mut recoveries = 0_u8;
        let mut recovery_window_start = Instant::now();
        Self::start_with_attach(
            move || {
                let result = if start_pending {
                    // The initial attach is the one explicit ensure/start. Later reconnects
                    // discover first, then use the source's bounded recovery mode if needed.
                    start_pending = false;
                    attach_gateway(AttachMode::Start)
                } else {
                    if recovery_window_start.elapsed() >= Duration::from_secs(60) {
                        recovery_window_start = Instant::now();
                        recoveries = 0;
                    }
                    match attach_gateway(AttachMode::Discover) {
                        Ok(connected) => Ok(connected),
                        Err(LocalAttachFailure::Refused(refusal))
                            if refusal.reason_code.as_deref() != Some("invalid_invocation")
                                && recoveries < 3 =>
                        {
                            recoveries = recoveries.saturating_add(1);
                            attach_gateway(AttachMode::Recover)
                        }
                        Err(error) => Err(error),
                    }
                };
                result.map_err(|error| error.to_string())
            },
            true,
        )
    }

    pub(crate) fn start_remote(
        base_url: String,
        auth_mode: RemoteAuthMode,
        credential: RemoteGatewayAuth,
    ) -> Self {
        Self::start_with_attach(
            move || attach_remote_gateway(&base_url, auth_mode, credential.clone()),
            false,
        )
    }

    fn start_with_attach(
        mut attach: impl FnMut() -> Result<(ConnectedGateway, GatewaySocket), String> + Send + 'static,
        load_sessions_http: bool,
    ) -> Self {
        let (status_sender, status_receiver) = mpsc::channel();
        let (event_sender, event_receiver) = mpsc::channel();
        let (command_sender, command_receiver) = mpsc::channel();
        let (plugin_update_all_sender, plugin_update_all_receiver) = mpsc::channel();
        let (http_sender, http_receiver) = mpsc::channel();
        let (project_tree_sender, project_tree_receiver) = mpsc::channel();
        let (cron_trigger_sender, cron_trigger_receiver) = mpsc::sync_channel(8);
        let (artifact_sender, artifact_receiver) = mpsc::channel();
        let (artifact_download_sender, artifact_download_receiver) = mpsc::channel();
        let (artifact_image_sender, artifact_image_receiver) = mpsc::channel();
        thread::Builder::new()
            .name("hermes-gateway-session-list".into())
            .spawn(move || {
                let mut retry_attempt = 0_u32;
                let mut connected_owner: Option<(String, String)> = None;
                let mut worker_receivers = Some((
                    plugin_update_all_receiver,
                    http_receiver,
                    project_tree_receiver,
                    cron_trigger_receiver,
                    artifact_receiver,
                    artifact_download_receiver,
                    artifact_image_receiver,
                ));
                let mut replay_cursors = HashMap::new();

                loop {
                    if command_receiver
                        .try_recv()
                        .is_err_and(|error| error == TryRecvError::Disconnected)
                    {
                        return;
                    }
                    match attach() {
                        Ok((connected, mut socket)) => {
                            let owner = (
                                connected.endpoint.profile_id.clone(),
                                connected.endpoint.instance_id.clone(),
                            );
                            if connected_owner
                                .as_ref()
                                .is_some_and(|expected| expected != &owner)
                            {
                                let _ = socket.close(None);
                                let _ = status_sender.send(Err(
                                    "Hermes Gateway identity changed during reconnect; reconnect manually to select the new owner".into(),
                                ));
                                return;
                            }
                            connected_owner.get_or_insert(owner);

                            if let Some((
                                plugin_update_all_receiver,
                                http_receiver,
                                project_tree_receiver,
                                cron_trigger_receiver,
                                artifact_receiver,
                                artifact_download_receiver,
                                artifact_image_receiver,
                            )) = worker_receivers.take()
                            {
                                spawn_gateway_workers(
                                    connected.endpoint.clone(),
                                    event_sender.clone(),
                                    plugin_update_all_receiver,
                                    http_receiver,
                                    project_tree_receiver,
                                    cron_trigger_receiver,
                                    artifact_receiver,
                                    artifact_download_receiver,
                                    artifact_image_receiver,
                                );
                            }

                            // A command queued against the failed socket must not be sent after
                            // reconnect. The app receives Disconnected and marks writes unknown.
                            if !discard_queued_gateway_commands(&command_receiver) {
                                let _ = socket.close(None);
                                return;
                            }
                            let connected_at = Instant::now();
                            if status_sender.send(Ok(connected.clone())).is_err() {
                                let _ = socket.close(None);
                                return;
                            }
                            replay_gateway_events(
                                &mut socket,
                                &mut replay_cursors,
                                &event_sender,
                            );

                            gateway_actor_with_replay(
                                &mut socket,
                                &command_receiver,
                                event_sender.clone(),
                                &connected.endpoint.profile_id,
                                Some(connected.endpoint.clone()),
                                &mut replay_cursors,
                            );
                            let _ = socket.close(None);
                            if command_receiver
                                .try_recv()
                                .is_err_and(|error| error == TryRecvError::Disconnected)
                            {
                                return;
                            }
                            retry_attempt = next_gateway_reconnect_attempt(
                                retry_attempt,
                                connected_at.elapsed(),
                            );
                            let delay = gateway_reconnect_delay_ms(
                                retry_attempt,
                                random_reconnect_sample(),
                            );
                            retry_attempt = retry_attempt.saturating_add(1);
                            let _ = status_sender.send(Err(format!(
                                "Hermes Gateway disconnected; retrying in {delay} ms"
                            )));
                            if !wait_for_gateway_retry(&command_receiver, delay) {
                                return;
                            }
                        }
                        Err(error) => {
                            let _ = status_sender.send(Err(error.clone()));
                            if is_terminal_gateway_reconnect_error(&error) {
                                return;
                            }
                            let delay = gateway_reconnect_delay_ms(
                                retry_attempt,
                                random_reconnect_sample(),
                            );
                            retry_attempt = retry_attempt.saturating_add(1);
                            if !wait_for_gateway_retry(&command_receiver, delay) {
                                return;
                            }
                        }
                    }
                }
            })
            .expect("failed to start Hermes gateway discovery worker");
        if load_sessions_http {
            let _ = http_sender.send(GatewayHttpCommand::LoadSessions);
        }
        Self {
            status_receiver,
            event_receiver,
            connection_id: None,
            command_sender,
            plugin_update_all_sender,
            http_sender,
            project_tree_sender,
            cron_trigger_sender,
            artifact_sender,
            artifact_download_sender,
            artifact_image_sender,
        }
    }

    pub fn poll(&self) -> Option<Result<ConnectedGateway, String>> {
        match self.status_receiver.try_recv() {
            Ok(result) => Some(result),
            Err(TryRecvError::Empty | TryRecvError::Disconnected) => None,
        }
    }

    /// Associates events from this discovery with the stable configured connection.
    ///
    /// Legacy callers may leave the ID unset; in that case polled events preserve
    /// `None` and continue to use the existing profile-scoped behavior.
    pub fn with_connection_id(mut self, connection_id: impl Into<String>) -> Self {
        self.connection_id = Some(connection_id.into());
        self
    }

    pub fn connection_id(&self) -> Option<&str> {
        self.connection_id.as_deref()
    }

    pub fn poll_event(&self) -> Option<GatewayEvent> {
        let mut event = self.event_receiver.try_recv().ok()?;
        match &mut event {
            GatewayEvent::SessionResumed { connection_id, .. }
            | GatewayEvent::SessionInterrupted { connection_id, .. }
            | GatewayEvent::SessionRuntimeRebound { connection_id, .. }
            | GatewayEvent::ComposerAttachmentAttached { connection_id, .. }
            | GatewayEvent::SessionBranched { connection_id, .. }
            | GatewayEvent::ForeignSessionsLoaded { connection_id, .. }
            | GatewayEvent::ForeignSessionPreviewLoaded { connection_id, .. }
            | GatewayEvent::ForeignSessionImported { connection_id, .. }
            | GatewayEvent::SlashCompletionLoaded { connection_id, .. }
            | GatewayEvent::DisplayReasoningLoaded { connection_id, .. }
            | GatewayEvent::DisplayReasoningSaved { connection_id, .. } => {
                *connection_id = self.connection_id.clone();
            }
            GatewayEvent::SessionCompressed { connection_id, .. } => {
                *connection_id = self.connection_id.clone();
            }
            GatewayEvent::ServerEvent { connection_id, .. } => {
                *connection_id = self.connection_id.clone();
            }
            GatewayEvent::ApprovalResponded { connection_id, .. }
            | GatewayEvent::ClarifyResponded { connection_id, .. }
            | GatewayEvent::ClarifyLocked { connection_id, .. }
            | GatewayEvent::ServerRequestReceived { connection_id, .. }
            | GatewayEvent::ServerRequestAnswered { connection_id, .. }
            | GatewayEvent::ConnectionResponded { connection_id, .. }
            | GatewayEvent::ConnectionTargetReissued { connection_id, .. } => {
                *connection_id = self.connection_id.clone();
            }
            _ => {}
        }
        Some(event)
    }

    /// Retire this connection and stop accepting its results in the current UI.
    ///
    /// Dropping the event receiver first makes every late event send fail. Dropping
    /// the command senders then disconnects the Gateway actor and the worker
    /// channels; the socket actor observes command disconnection after its bounded
    /// read timeout. This does not join in-flight HTTP requests or an attach still
    /// blocked in network setup, so callers must still fence results by connection
    /// identity when more than one connection can be active.
    pub fn shutdown(self) {
        let Self {
            status_receiver,
            event_receiver,
            connection_id: _,
            command_sender,
            plugin_update_all_sender,
            http_sender,
            project_tree_sender,
            cron_trigger_sender,
            artifact_sender,
            artifact_download_sender,
            artifact_image_sender,
        } = self;

        drop((status_receiver, event_receiver));
        drop((
            command_sender,
            plugin_update_all_sender,
            http_sender,
            project_tree_sender,
            cron_trigger_sender,
            artifact_sender,
            artifact_download_sender,
            artifact_image_sender,
        ));
    }

    pub fn resume_session(
        &self,
        request_id: String,
        session_id: String,
        profile: Option<String>,
    ) -> Result<(), String> {
        self.command_sender
            .send(GatewayCommand::ResumeSession {
                request_id,
                session_id,
                profile,
            })
            .map_err(|_| "Hermes gateway connection has closed".to_owned())
    }

    pub fn set_session_cwd(
        &self,
        request_id: String,
        session_id: String,
        stored_session_id: String,
        profile: Option<String>,
        connection_id: Option<String>,
        cwd: String,
    ) -> Result<(), String> {
        if !valid_bounded_tree_id(&session_id)
            || !valid_bounded_tree_id(&stored_session_id)
            || profile
                .as_deref()
                .is_some_and(|profile| !valid_bounded_tree_id(profile))
            || connection_id
                .as_deref()
                .is_some_and(|connection_id| !valid_bounded_tree_id(connection_id))
        {
            return Err("Hermes working-directory change requires a valid session owner".into());
        }
        if cwd.trim().is_empty() || cwd.len() > 4096 || cwd.chars().any(char::is_control) {
            return Err(
                "Hermes working directory must be a non-empty path of at most 4096 bytes".into(),
            );
        }
        self.command_sender
            .send(GatewayCommand::SetSessionCwd {
                request_id,
                session_id,
                stored_session_id,
                profile,
                connection_id,
                cwd,
            })
            .map_err(|_| "Hermes gateway connection has closed".to_owned())
    }

