    /// Answer a session-scoped `connection.request` event through the normal
    /// `connection.respond` RPC. Credential values in `result` are sent only
    /// over the owning Gateway connection and are never copied into a receipt.
    pub fn respond_connection(
        &self,
        request_id: String,
        session_id: String,
        op_id: String,
        profile: Option<String>,
        result: serde_json::Value,
    ) -> Result<(), String> {
        if request_id.is_empty() || session_id.is_empty() || op_id.is_empty() {
            return Err("Hermes connection response identifiers must not be empty".into());
        }
        if !result.is_object() {
            return Err("Hermes connection response must be an object".into());
        }
        self.command_sender
            .send(GatewayCommand::RespondConnection {
                request_id,
                session_id,
                op_id,
                profile,
                result,
            })
            .map_err(|_| "Hermes gateway connection has closed".to_owned())
    }

    /// Reissue one failed or expired target on its existing open operation.
    /// Hermes remains the authority for whether that target can be retried.
    pub fn reissue_connection_target(
        &self,
        request_id: String,
        session_id: String,
        op_id: String,
        target_name: String,
        profile: Option<String>,
    ) -> Result<(), String> {
        if request_id.is_empty()
            || session_id.is_empty()
            || op_id.is_empty()
            || target_name.trim().is_empty()
        {
            return Err("Hermes connection retry identifiers must not be empty".into());
        }
        self.command_sender
            .send(GatewayCommand::ReissueConnectionTarget {
                request_id,
                session_id,
                op_id,
                target_name,
                profile,
            })
            .map_err(|_| "Hermes gateway connection has closed".to_owned())
    }

