fn display_reasoning_config_patch(enabled: bool) -> serde_json::Value {
    serde_json::json!({
        "config": {
            "display": {
                "show_reasoning": enabled,
                "platforms": {"cli": {"show_reasoning": enabled}},
            }
        }
    })
}

fn save_display_reasoning_http(
    endpoint: &GatewayEndpoint,
    profile: Option<&str>,
    enabled: bool,
) -> Result<bool, String> {
    let profile_id = profile.unwrap_or(&endpoint.profile_id);
    let url = format!(
        "{}/api/config{}",
        endpoint.api_origin.trim_end_matches('/'),
        session_profile_suffix(profile_id)
    );
    let response = if endpoint.remote_auth.is_some() {
        request_remote_gateway_mutation(
            endpoint,
            "PUT",
            &url,
            display_reasoning_config_patch(enabled),
        )?
    } else {
        if !is_bare_loopback_origin(&endpoint.api_origin) {
            return Err(
                "Hermes display configuration requires the verified loopback API origin".into(),
            );
        }
        let ticket = mint_windows_ticket(endpoint, "native-http", None)?;
        save_display_reasoning_local(&endpoint.api_origin, ticket.as_str(), profile_id, enabled)?
    };
    if response.get("ok").and_then(serde_json::Value::as_bool) != Some(true) {
        return Err("Hermes did not confirm the reasoning setting was saved".into());
    }
    Ok(enabled)
}

fn save_display_reasoning_local(
    api_origin: &str,
    ticket: &str,
    profile_id: &str,
    enabled: bool,
) -> Result<serde_json::Value, String> {
    validate_http_ticket(ticket)?;
    if !is_bare_loopback_origin(api_origin) {
        return Err(
            "Hermes display configuration requires the verified loopback API origin".into(),
        );
    }
    let url = format!(
        "{}/api/config{}",
        api_origin.trim_end_matches('/'),
        session_profile_suffix(profile_id)
    );
    cron_local_gateway_http_request_with_ticket(
        api_origin,
        ticket,
        "PUT",
        &url,
        Some(display_reasoning_config_patch(enabled)),
    )
}

fn load_repo_scan_config_http(
    endpoint: &GatewayEndpoint,
    profile: Option<&str>,
) -> Result<RepoScanPolicy, String> {
    let profile_id = profile.unwrap_or(&endpoint.profile_id);
    let url = format!(
        "{}/api/config{}",
        endpoint.api_origin.trim_end_matches('/'),
        session_profile_suffix(profile_id)
    );
    if endpoint.remote_auth.is_some() {
        let config: serde_json::Value = request_remote_gateway_json(endpoint, &url)?;
        return Ok(repo_scan_policy_from_config(&config));
    }
    if !is_bare_loopback_origin(&endpoint.api_origin) {
        return Err(
            "Hermes repo discovery settings require the verified loopback API origin".into(),
        );
    }
    let ticket = mint_windows_ticket(endpoint, "native-http", None)?;
    read_repo_scan_config_local(&endpoint.api_origin, ticket.as_str(), profile_id)
}

fn read_repo_scan_config_local(
    api_origin: &str,
    ticket: &str,
    profile_id: &str,
) -> Result<RepoScanPolicy, String> {
    validate_http_ticket(ticket)?;
    if !is_bare_loopback_origin(api_origin) {
        return Err(
            "Hermes repo discovery settings require the verified loopback API origin".into(),
        );
    }
    let url = format!(
        "{}/api/config{}",
        api_origin.trim_end_matches('/'),
        session_profile_suffix(profile_id)
    );
    let config: serde_json::Value = request_gateway_json(api_origin, ticket, &url)?;
    Ok(repo_scan_policy_from_config(&config))
}

fn save_repo_scan_config_http(
    endpoint: &GatewayEndpoint,
    profile: Option<&str>,
    policy: &RepoScanPolicy,
) -> Result<RepoScanPolicy, String> {
    if !repo_scan_policy_is_bounded(policy) {
        return Err("Hermes repo discovery settings exceed their bounded schema".into());
    }
    let profile_id = profile.unwrap_or(&endpoint.profile_id);
    let url = format!(
        "{}/api/config{}",
        endpoint.api_origin.trim_end_matches('/'),
        session_profile_suffix(profile_id)
    );
    // Hermes config PUT deep-merges sparse patches. Sending only this section
    // preserves all unrelated profile settings and avoids a read/overwrite race.
    let body = repo_scan_config_patch(policy);
    let response: serde_json::Value = if endpoint.remote_auth.is_some() {
        request_remote_gateway_mutation(endpoint, "PUT", &url, body)?
    } else {
        if !is_bare_loopback_origin(&endpoint.api_origin) {
            return Err(
                "Hermes repo discovery settings require the verified loopback API origin".into(),
            );
        }
        let ticket = mint_windows_ticket(endpoint, "native-http", None)?;
        validate_http_ticket(&ticket)?;
        save_repo_scan_config_local(&endpoint.api_origin, ticket.as_str(), profile_id, policy)?
    };
    if response.get("ok").and_then(serde_json::Value::as_bool) != Some(true) {
        return Err("Hermes did not confirm repo discovery settings were saved".into());
    }
    Ok(policy.clone())
}

fn repo_scan_policy_is_bounded(policy: &RepoScanPolicy) -> bool {
    serde_json::to_vec(policy)
        .is_ok_and(|encoded| encoded.len() as u64 <= GATEWAY_HTTP_RESPONSE_LIMIT)
}

fn repo_scan_config_patch(policy: &RepoScanPolicy) -> serde_json::Value {
    serde_json::json!({
        "config": {
            "desktop": {
                "repo_scan_enabled": policy.enabled,
                "repo_scan_roots": policy.roots,
                "repo_scan_exclude_paths": policy.exclude_paths,
            }
        }
    })
}

fn save_repo_scan_config_local(
    api_origin: &str,
    ticket: &str,
    profile_id: &str,
    policy: &RepoScanPolicy,
) -> Result<serde_json::Value, String> {
    validate_http_ticket(ticket)?;
    if !is_bare_loopback_origin(api_origin) {
        return Err(
            "Hermes repo discovery settings require the verified loopback API origin".into(),
        );
    }
    let url = format!(
        "{}/api/config{}",
        api_origin.trim_end_matches('/'),
        session_profile_suffix(profile_id)
    );
    cron_local_gateway_http_request_with_ticket(
        api_origin,
        ticket,
        "PUT",
        &url,
        Some(repo_scan_config_patch(policy)),
    )
}

fn repo_scan_policy_from_config(config: &serde_json::Value) -> RepoScanPolicy {
    let desktop = config.get("desktop").and_then(serde_json::Value::as_object);
    let enabled = desktop
        .and_then(|desktop| desktop.get("repo_scan_enabled"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(true);
    let strings = |key: &str| {
        desktop
            .and_then(|desktop| desktop.get(key))
            .and_then(serde_json::Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(serde_json::Value::as_str)
            .map(str::to_owned)
            .collect()
    };
    RepoScanPolicy {
        enabled,
        roots: strings("repo_scan_roots"),
        exclude_paths: strings("repo_scan_exclude_paths"),
    }
}

const FALLBACK_ROUTE_LIMIT: usize = 64;

fn valid_plugin_setting_env_name(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 256
        && value.bytes().enumerate().all(|(index, byte)| {
            byte == b'_' || byte.is_ascii_uppercase() || (index > 0 && byte.is_ascii_digit())
        })
        && value
            .as_bytes()
            .first()
            .is_some_and(|byte| byte.is_ascii_uppercase() || *byte == b'_')
}

fn save_agent_plugin_setting_secret_http(
    endpoint: &GatewayEndpoint,
    profile: Option<&str>,
    key: &str,
    value: &str,
) -> Result<(), String> {
    if !valid_plugin_setting_env_name(key) || value.is_empty() || value.len() > 64 * 1024 {
        return Err("Plugin secret settings are invalid or exceed their bounded schema".into());
    }
    let profile_id = profile.unwrap_or(&endpoint.profile_id);
    let url = format!(
        "{}/api/env{}",
        endpoint.api_origin.trim_end_matches('/'),
        session_profile_suffix(profile_id)
    );
    let body = serde_json::json!({"key": key, "value": value});
    let response: serde_json::Value = if endpoint.remote_auth.is_some() {
        request_remote_gateway_mutation(endpoint, "PUT", &url, body)?
    } else {
        if !is_bare_loopback_origin(&endpoint.api_origin) {
            return Err("Hermes plugin secrets require the verified loopback API origin".into());
        }
        let ticket = mint_windows_ticket(endpoint, "native-http", None)?;
        validate_http_ticket(&ticket)?;
        save_plugin_setting_secret_local(
            &endpoint.api_origin,
            ticket.as_str(),
            profile_id,
            key,
            value,
        )?
    };
    if response.get("ok").and_then(serde_json::Value::as_bool) != Some(true) {
        return Err("Hermes did not confirm the plugin secret was saved".into());
    }
    Ok(())
}

fn save_plugin_setting_secret_local(
    api_origin: &str,
    ticket: &str,
    profile_id: &str,
    key: &str,
    value: &str,
) -> Result<serde_json::Value, String> {
    validate_http_ticket(ticket)?;
    if !is_bare_loopback_origin(api_origin) {
        return Err("Hermes plugin secrets require the verified loopback API origin".into());
    }
    if !valid_plugin_setting_env_name(key) || value.is_empty() || value.len() > 64 * 1024 {
        return Err("Plugin secret settings are invalid or exceed their bounded schema".into());
    }
    let url = format!(
        "{}/api/env{}",
        api_origin.trim_end_matches('/'),
        session_profile_suffix(profile_id)
    );
    cron_local_gateway_http_request_with_ticket(
        api_origin,
        ticket,
        "PUT",
        &url,
        Some(serde_json::json!({"key": key, "value": value})),
    )
}

fn load_fallback_providers_http(
    endpoint: &GatewayEndpoint,
    profile: Option<&str>,
) -> Result<Vec<serde_json::Value>, String> {
    let profile_id = profile.unwrap_or(&endpoint.profile_id);
    let url = format!(
        "{}/api/config{}",
        endpoint.api_origin.trim_end_matches('/'),
        session_profile_suffix(profile_id)
    );
    if endpoint.remote_auth.is_some() {
        let config: serde_json::Value = request_remote_gateway_json(endpoint, &url)?;
        return fallback_providers_from_config(&config);
    }
    if !is_bare_loopback_origin(&endpoint.api_origin) {
        return Err(
            "Hermes fallback model settings require the verified loopback API origin".into(),
        );
    }
    let ticket = mint_windows_ticket(endpoint, "native-http", None)?;
    read_fallback_providers_local(&endpoint.api_origin, ticket.as_str(), profile_id)
}

fn read_fallback_providers_local(
    api_origin: &str,
    ticket: &str,
    profile_id: &str,
) -> Result<Vec<serde_json::Value>, String> {
    validate_http_ticket(ticket)?;
    if !is_bare_loopback_origin(api_origin) {
        return Err(
            "Hermes fallback model settings require the verified loopback API origin".into(),
        );
    }
    let url = format!(
        "{}/api/config{}",
        api_origin.trim_end_matches('/'),
        session_profile_suffix(profile_id)
    );
    let config: serde_json::Value = request_gateway_json(api_origin, ticket, &url)?;
    fallback_providers_from_config(&config)
}

fn save_fallback_providers_http(
    endpoint: &GatewayEndpoint,
    profile: Option<&str>,
    routes: &[serde_json::Value],
) -> Result<Vec<serde_json::Value>, String> {
    let routes = normalize_fallback_providers(routes.to_vec())?;
    if !fallback_providers_are_bounded(&routes) {
        return Err("Hermes fallback model settings exceed their bounded schema".into());
    }
    let profile_id = profile.unwrap_or(&endpoint.profile_id);
    let url = format!(
        "{}/api/config{}",
        endpoint.api_origin.trim_end_matches('/'),
        session_profile_suffix(profile_id)
    );
    let body = fallback_providers_config_patch(&routes);
    let response: serde_json::Value = if endpoint.remote_auth.is_some() {
        request_remote_gateway_mutation(endpoint, "PUT", &url, body)?
    } else {
        if !is_bare_loopback_origin(&endpoint.api_origin) {
            return Err(
                "Hermes fallback model settings require the verified loopback API origin".into(),
            );
        }
        let ticket = mint_windows_ticket(endpoint, "native-http", None)?;
        validate_http_ticket(&ticket)?;
        save_fallback_providers_local(&endpoint.api_origin, ticket.as_str(), profile_id, &routes)?
    };
    if response.get("ok").and_then(serde_json::Value::as_bool) != Some(true) {
        return Err("Hermes did not confirm fallback model settings were saved".into());
    }
    Ok(routes)
}

fn save_fallback_providers_local(
    api_origin: &str,
    ticket: &str,
    profile_id: &str,
    routes: &[serde_json::Value],
) -> Result<serde_json::Value, String> {
    validate_http_ticket(ticket)?;
    if !is_bare_loopback_origin(api_origin) {
        return Err(
            "Hermes fallback model settings require the verified loopback API origin".into(),
        );
    }
    let routes = normalize_fallback_providers(routes.to_vec())?;
    if !fallback_providers_are_bounded(&routes) {
        return Err("Hermes fallback model settings exceed their bounded schema".into());
    }
    let url = format!(
        "{}/api/config{}",
        api_origin.trim_end_matches('/'),
        session_profile_suffix(profile_id)
    );
    cron_local_gateway_http_request_with_ticket(
        api_origin,
        ticket,
        "PUT",
        &url,
        Some(fallback_providers_config_patch(&routes)),
    )
}

fn fallback_providers_from_config(
    config: &serde_json::Value,
) -> Result<Vec<serde_json::Value>, String> {
    let Some(value) = config.get("fallback_providers") else {
        return Ok(Vec::new());
    };
    let routes = value
        .as_array()
        .ok_or_else(|| "Hermes fallback_providers must be a list".to_owned())?;
    normalize_fallback_providers(routes.clone())
}

fn normalize_fallback_providers(
    routes: Vec<serde_json::Value>,
) -> Result<Vec<serde_json::Value>, String> {
    if routes.len() > FALLBACK_ROUTE_LIMIT {
        return Err("Hermes returned too many fallback model routes".into());
    }
    let mut normalized = Vec::with_capacity(routes.len());
    for (index, route) in routes.into_iter().enumerate() {
        let value = match route {
            serde_json::Value::Object(_) => route,
            serde_json::Value::String(value) => {
                let (provider, model) = value.split_once('/').ok_or_else(|| {
                    format!(
                        "Hermes fallback route {} must use provider/model format",
                        index + 1
                    )
                })?;
                serde_json::json!({"provider": provider, "model": model})
            }
            _ => {
                return Err(format!(
                    "Hermes fallback route {} must be an object or legacy provider/model string",
                    index + 1
                ));
            }
        };
        let object = value
            .as_object()
            .ok_or_else(|| format!("Hermes fallback route {} is invalid", index + 1))?;
        for field in ["provider", "model"] {
            let Some(value) = object.get(field).and_then(serde_json::Value::as_str) else {
                return Err(format!(
                    "Hermes fallback route {} has no valid {field}",
                    index + 1
                ));
            };
            if value.trim().is_empty()
                || value.len() > CRON_FORM_MODEL_LIMIT
                || value.chars().any(char::is_control)
            {
                return Err(format!(
                    "Hermes fallback route {} has an invalid {field}",
                    index + 1
                ));
            }
        }
        normalized.push(value);
    }
    if !fallback_providers_are_bounded(&normalized) {
        return Err("Hermes fallback model settings exceed their bounded schema".into());
    }
    Ok(normalized)
}

fn fallback_providers_are_bounded(routes: &[serde_json::Value]) -> bool {
    routes.len() <= FALLBACK_ROUTE_LIMIT
        && serde_json::to_vec(routes)
            .is_ok_and(|encoded| encoded.len() as u64 <= GATEWAY_HTTP_RESPONSE_LIMIT)
}

fn fallback_providers_config_patch(routes: &[serde_json::Value]) -> serde_json::Value {
    serde_json::json!({"config": {"fallback_providers": routes}})
}

fn redact_secrets_from_config(config: &serde_json::Value) -> Result<bool, String> {
    let Some(security) = config.get("security") else {
        return Ok(true);
    };
    let Some(security) = security.as_object() else {
        return Err("Hermes security settings must be an object".into());
    };
    match security.get("redact_secrets") {
        None => Ok(true),
        Some(value) => value
            .as_bool()
            .ok_or_else(|| "Hermes security.redact_secrets must be a boolean".into()),
    }
}

fn redact_secrets_config_patch(enabled: bool) -> serde_json::Value {
    serde_json::json!({"config":{"security":{"redact_secrets":enabled}}})
}

