    #[test]
    fn prompt_edit_uses_stable_row_and_explicit_deep_cut_confirmation() {
        let shallow = prompt_edit_rpc_params(
            "runtime-3",
            Some("profile-3"),
            "edit-1",
            "updated",
            41,
            false,
            &[10, 11],
        )
        .unwrap();
        assert_eq!(shallow["session_id"], "runtime-3");
        assert_eq!(shallow["profile"], "profile-3");
        assert_eq!(shallow["confirm_truncate"], true);
        assert_eq!(shallow["confirm_empty_truncate"], true);
        assert_eq!(shallow["truncate_before_row_id"], 41);
        assert_eq!(
            shallow["rebind_survivor_row_ids"],
            serde_json::json!([10, 11])
        );
        assert!(shallow.get("confirm_deep_truncate").is_none());

        let deep =
            prompt_edit_rpc_params("runtime-3", None, "edit-2", "updated", 42, true, &[]).unwrap();
        assert_eq!(deep["confirm_deep_truncate"], true);
        assert_eq!(deep["truncate_before_row_id"], 42);
        assert!(
            prompt_edit_rpc_params("runtime-3", None, "edit-3", "updated", 0, true, &[]).is_err()
        );
    }

    #[test]
    fn gateway_discovery_shutdown_closes_actor_and_rejects_late_events() {
        let (_status_sender, status_receiver) = mpsc::channel();
        let (event_sender, event_receiver) = mpsc::channel();
        let (command_sender, command_receiver) = mpsc::channel();
        let (actor_stopped_sender, actor_stopped_receiver) = mpsc::channel();
        let actor = thread::spawn(move || {
            while command_receiver.recv().is_ok() {}
            actor_stopped_sender
                .send(())
                .expect("report actor shutdown");
        });
        let late_event_sender = event_sender.clone();

        let (plugin_update_all_sender, plugin_update_all_receiver) = mpsc::channel();
        let (http_sender, http_receiver) = mpsc::channel();
        let (project_tree_sender, project_tree_receiver) = mpsc::channel();
        let (cron_trigger_sender, cron_trigger_receiver) = mpsc::sync_channel(1);
        let (artifact_sender, artifact_receiver) = mpsc::channel();
        let (artifact_download_sender, artifact_download_receiver) = mpsc::channel();
        let (artifact_image_sender, artifact_image_receiver) = mpsc::channel();
        drop((
            plugin_update_all_receiver,
            http_receiver,
            project_tree_receiver,
            cron_trigger_receiver,
            artifact_receiver,
            artifact_download_receiver,
            artifact_image_receiver,
        ));

        let discovery = GatewayDiscovery {
            status_receiver,
            event_receiver,
            connection_id: None,
            command_sender,
            plugin_update_all_sender,
            http_sender,
            project_tree_sender,
            cron_trigger_sender,
            artifact_sender,
            artifact_download_sender,
            artifact_image_sender,
        };
        discovery.shutdown();

        actor_stopped_receiver
            .recv_timeout(Duration::from_millis(250))
            .expect("actor should observe its closed command channel");
        actor.join().expect("actor thread should terminate");
        assert!(
            late_event_sender
                .send(GatewayEvent::Disconnected("late event".into()))
                .is_err()
        );
    }

    #[test]
    fn poll_event_attaches_stable_connection_id_to_session_resume() {
        let (legacy, legacy_events) = GatewayDiscovery::for_test_event_poll(None);
        assert_eq!(legacy.connection_id(), None);
        legacy_events
            .send(GatewayEvent::SessionResumed {
                request_id: "legacy-resume".into(),
                session_id: "stored-session".into(),
                profile: Some("work".into()),
                connection_id: None,
                result: Err("offline".into()),
            })
            .expect("queue legacy resume result");
        assert!(matches!(
            legacy.poll_event(),
            Some(GatewayEvent::SessionResumed {
                request_id,
                session_id,
                profile: Some(profile),
                connection_id: None,
                result: Err(error),
            }) if request_id == "legacy-resume"
                && session_id == "stored-session"
                && profile == "work"
                && error == "offline"
        ));

        let (discovery, events) = GatewayDiscovery::for_test_event_poll(None);
        let discovery = discovery.with_connection_id("saved-remote-a");
        assert_eq!(discovery.connection_id(), Some("saved-remote-a"));
        events
            .send(GatewayEvent::SessionResumed {
                request_id: "owned-resume".into(),
                session_id: "stored-session".into(),
                profile: Some("work".into()),
                connection_id: None,
                result: Err("offline".into()),
            })
            .expect("queue owned resume result");
        assert!(matches!(
            discovery.poll_event(),
            Some(GatewayEvent::SessionResumed {
                request_id,
                session_id,
                profile: Some(profile),
                connection_id: Some(connection_id),
                result: Err(error),
            }) if request_id == "owned-resume"
                && session_id == "stored-session"
                && profile == "work"
                && connection_id == "saved-remote-a"
                && error == "offline"
        ));

        events
            .send(GatewayEvent::ServerRequestReceived {
                id: "approval-request".into(),
                method: "approval".into(),
                params: serde_json::json!({"session_id":"runtime","profile":"work"}),
                connection_id: None,
            })
            .expect("queue server request");
        assert!(matches!(
            discovery.poll_event(),
            Some(GatewayEvent::ServerRequestReceived {
                id,
                connection_id: Some(connection_id),
                ..
            }) if id == "approval-request" && connection_id == "saved-remote-a"
        ));

        events
            .send(GatewayEvent::ServerRequestAnswered {
                id: "approval-request".into(),
                result: Ok(()),
                profile: Some("work".into()),
                connection_id: None,
            })
            .expect("queue server request receipt");
        assert!(matches!(
            discovery.poll_event(),
            Some(GatewayEvent::ServerRequestAnswered {
                id,
                profile: Some(profile),
                connection_id: Some(connection_id),
                ..
            }) if id == "approval-request"
                && profile == "work"
                && connection_id == "saved-remote-a"
        ));

        events
            .send(GatewayEvent::ApprovalResponded {
                request_id: "approval-response".into(),
                session_id: "runtime".into(),
                profile: Some("work".into()),
                prompt_id: "prompt".into(),
                choice: "once".into(),
                result: Ok(()),
                outcome_unknown: false,
                connection_id: None,
            })
            .expect("queue approval response receipt");
        assert!(matches!(
            discovery.poll_event(),
            Some(GatewayEvent::ApprovalResponded {
                request_id,
                profile: Some(profile),
                connection_id: Some(connection_id),
                ..
            }) if request_id == "approval-response"
                && profile == "work"
                && connection_id == "saved-remote-a"
        ));
    }

