    #[test]
    fn profile_and_stored_transcript_events_preserve_connection_and_endpoint_fences() {
        use std::io::Write as _;

        let listener = TcpListener::bind("127.0.0.1:0").expect("bind profile/transcript fixture");
        let address = listener
            .local_addr()
            .expect("profile/transcript fixture address");
        let server = thread::spawn(move || {
            for (expected_path, body) in [
                (
                    "/hermes/api/profiles",
                    r#"{"profiles":[{"name":"default"},{"name":"research"}]}"#,
                ),
                (
                    "/hermes/api/sessions/legacy-session-7/messages?limit=120&offset=0&order=latest&include_compacted=true",
                    r#"{"session_id":"legacy-session-7","profile":"research","messages":[{"role":"user","content":"history"}],"pagination":{"limit":120,"offset":0,"order":"latest","returned":1}}"#,
                ),
            ] {
                let (mut stream, _) = listener
                    .accept()
                    .expect("accept profile/transcript request");
                let request = read_http_fixture_request(&mut stream);
                let lower = request.to_ascii_lowercase();
                assert!(request.starts_with(&format!("GET {expected_path} HTTP/1.1\r\n")));
                assert!(lower.contains("x-hermes-session-token: fixture-session-token\r\n"));
                assert!(!lower.contains("x-hermes-gateway-ticket:"));
                write!(
                    stream,
                    "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                    body.len(),
                    body
                )
                .expect("write profile/transcript response");
            }
        });

        let endpoint = GatewayEndpoint {
            profile_id: "remote-profile".into(),
            instance_id: "endpoint-instance-7".into(),
            authority_epoch: 9,
            runtime_protocol: 1,
            api_origin: format!("http://{address}/hermes"),
            capabilities: vec![],
            control_home: None,
            remote_auth: Some(RemoteGatewayAuth::Token(Zeroizing::new(
                "fixture-session-token".into(),
            ))),
        };
        let (command_tx, command_rx) = mpsc::channel();
        let (event_tx, event_rx) = mpsc::channel();
        let actor = thread::spawn(move || gateway_http_actor(endpoint, command_rx, event_tx));

        command_tx
            .send(GatewayHttpCommand::LoadProfiles {
                request_id: "profiles-r1".into(),
                connection_id: Some("saved-gateway".into()),
                instance_id: "endpoint-instance-7".into(),
                authority_epoch: 9,
            })
            .expect("queue profile list");
        assert!(matches!(
            event_rx.recv_timeout(Duration::from_secs(3)).expect("profile list event"),
            GatewayEvent::ProfilesLoaded {
                request_id,
                connection_id,
                instance_id,
                authority_epoch,
                result: Ok(names),
            } if request_id == "profiles-r1"
                && connection_id.as_deref() == Some("saved-gateway")
                && instance_id == "endpoint-instance-7"
                && authority_epoch == 9
                && names == ["default", "research"]
        ));

        command_tx
            .send(GatewayHttpCommand::LoadStoredTranscript {
                request_id: "stored-r1".into(),
                session_id: "legacy-session-7".into(),
                connection_id: Some("saved-gateway".into()),
                instance_id: "endpoint-instance-7".into(),
                authority_epoch: 9,
            })
            .expect("queue ID-only stored transcript");
        assert!(matches!(
            event_rx.recv_timeout(Duration::from_secs(3)).expect("stored transcript event"),
            GatewayEvent::StoredTranscriptLoaded {
                request_id,
                session_id,
                connection_id,
                instance_id,
                authority_epoch,
                result: Ok(page),
            } if request_id == "stored-r1"
                && session_id == "legacy-session-7"
                && connection_id.as_deref() == Some("saved-gateway")
                && instance_id == "endpoint-instance-7"
                && authority_epoch == 9
                && page.profile.as_deref() == Some("research")
                && page.messages.len() == 1
        ));

        command_tx
            .send(GatewayHttpCommand::LoadProfiles {
                request_id: "profiles-stale".into(),
                connection_id: Some("saved-gateway".into()),
                instance_id: "old-instance".into(),
                authority_epoch: 8,
            })
            .expect("queue stale endpoint request");
        assert!(matches!(
            event_rx.recv_timeout(Duration::from_secs(1)).expect("stale identity event"),
            GatewayEvent::ProfilesLoaded {
                request_id,
                result: Err(error),
                ..
            } if request_id == "profiles-stale" && error.contains("stale endpoint")
        ));
        drop(command_tx);
        actor.join().expect("HTTP actor exits after sender closes");
        server.join().expect("profile/transcript fixture exits");
    }

    #[test]
    fn bot_roster_read_uses_profiles_list_with_explicit_profile_scope() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind profiles.list fixture");
        let address = listener
            .local_addr()
            .expect("profiles.list fixture address");
        let server = thread::spawn(move || {
            let (stream, _) = listener.accept().expect("accept profiles.list client");
            let mut socket = tungstenite::accept(stream).expect("accept WebSocket");
            let request: serde_json::Value =
                match socket.read().expect("read profiles.list request") {
                    Message::Text(text) => serde_json::from_str(&text).expect("parse request"),
                    other => panic!("expected profiles.list request, got {other:?}"),
                };
            assert_eq!(request["method"], "profiles.list");
            assert_eq!(request["params"], json!({"profile":"fixture-profile"}));
            let id = request["id"].as_u64().expect("numeric RPC id");
            socket.send(Message::Text(json!({"jsonrpc":"2.0","id":id,"result":{
                "bot_mode_protocol":true,
                "profiles":[{"name":"researcher","display_name":"Researcher","title":"Analyst"}]
            }}).to_string().into())).expect("send profiles.list response");
            socket.close(None).expect("close fixture WebSocket");
        });
        let (mut socket, _) =
            tungstenite::connect(format!("ws://{address}/api/ws")).expect("connect fixture");
        if let tungstenite::stream::MaybeTlsStream::Plain(stream) = socket.get_mut() {
            stream
                .set_read_timeout(Some(Duration::from_millis(50)))
                .expect("configure fixture read timeout");
        }
        let (command_tx, command_rx) = mpsc::channel();
        let (event_tx, event_rx) = mpsc::channel();
        let actor = thread::spawn(move || gateway_actor(&mut socket, &command_rx, event_tx));
        command_tx
            .send(GatewayCommand::LoadBotRoster {
                request_id: "bot-roster-1".into(),
                profile: "fixture-profile".into(),
            })
            .expect("queue profiles.list read");
        assert!(
            matches!(event_rx.recv_timeout(Duration::from_secs(3)).expect("profiles.list result"),
            GatewayEvent::BotRosterLoaded { request_id, profile, result: Ok(snapshot) }
                if request_id == "bot-roster-1" && profile == "fixture-profile"
                    && snapshot.bot_mode_protocol == Some(true)
                    && snapshot.profiles[0].name == "researcher")
        );
        drop(command_tx);
        actor.join().expect("gateway actor exits after peer close");
        server.join().expect("fixture server exits");
    }

    #[test]
    fn project_list_read_uses_pinned_rpc_and_explicit_profile_scope() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind projects.list fixture");
        let address = listener
            .local_addr()
            .expect("projects.list fixture address");
        let server = thread::spawn(move || {
            let (stream, _) = listener.accept().expect("accept projects.list client");
            let mut socket = tungstenite::accept(stream).expect("accept WebSocket");
            let read_request =
                |socket: &mut tungstenite::WebSocket<TcpStream>| -> serde_json::Value {
                    match socket.read().expect("read projects.list request") {
                        Message::Text(text) => serde_json::from_str(&text).expect("parse request"),
                        other => panic!("expected projects.list request, got {other:?}"),
                    }
                };
            let first = read_request(&mut socket);
            assert_eq!(first["jsonrpc"], "2.0");
            assert_eq!(first["method"], "projects.list");
            assert_eq!(first["params"], json!({"profile":"fixture-profile"}));
            let first_id = first["id"].as_u64().expect("numeric RPC id");
            assert_eq!(first_id, 5);

            // The current actor blocks on each RPC, so a queued second command is not
            // multiplexed onto the socket until the first response is settled.
            socket
                .get_mut()
                .set_read_timeout(Some(Duration::from_millis(50)))
                .expect("set bounded check for a concurrent request");
            assert!(
                matches!(
                    socket.read(),
                    Err(tungstenite::Error::Io(ref error))
                        if matches!(error.kind(), io::ErrorKind::TimedOut | io::ErrorKind::WouldBlock)
                ),
                "the serial Gateway actor must not send the queued second RPC while the first is pending"
            );
            socket
                .get_mut()
                .set_read_timeout(None)
                .expect("restore fixture socket read timeout");

            socket
                .send(Message::Text(
                    json!({"jsonrpc":"2.0","id":first_id,"result":{
                        "active_id":"p_demo",
                        "projects":[{"id":"p_demo","slug":"demo","name":"Demo",
                            "description":null,"icon":null,"color":null,"board_slug":null,
                            "primary_path":"C:/work/demo","archived":false,"created_at":1.0,
                            "folders":[]}]
                    }})
                    .to_string()
                    .into(),
                ))
                .expect("send first projects.list response");

            let second = read_request(&mut socket);
            assert_eq!(second["jsonrpc"], "2.0");
            assert_eq!(second["method"], "projects.list");
            assert_eq!(second["params"], json!({"profile":"fixture-profile"}));
            let second_id = second["id"].as_u64().expect("numeric RPC id");
            assert_eq!(second_id, first_id + 1);

            // A delayed reply from the completed request must not settle the newer request.
            socket
                .send(Message::Text(
                    json!({"jsonrpc":"2.0","id":first_id,"result":{
                        "active_id":"p_stale",
                        "projects":[{"id":"p_stale","slug":"stale","name":"Stale",
                            "description":null,"icon":null,"color":null,"board_slug":null,
                            "primary_path":"C:/work/stale","archived":false,"created_at":1.0,
                            "folders":[]}]
                    }})
                    .to_string()
                    .into(),
                ))
                .expect("send stale projects.list response");
            socket
                .send(Message::Text(
                    json!({"jsonrpc":"2.0","id":second_id,"result":{
                        "active_id":"p_second",
                        "projects":[{"id":"p_second","slug":"second","name":"Second",
                            "description":null,"icon":null,"color":null,"board_slug":null,
                            "primary_path":"C:/work/second","archived":false,"created_at":2.0,
                            "folders":[]}]
                    }})
                    .to_string()
                    .into(),
                ))
                .expect("send second projects.list response");
            socket.close(None).expect("close fixture WebSocket");
        });
        let (mut socket, _) =
            tungstenite::connect(format!("ws://{address}/api/ws")).expect("connect fixture");
        if let tungstenite::stream::MaybeTlsStream::Plain(stream) = socket.get_mut() {
            stream
                .set_read_timeout(Some(Duration::from_millis(50)))
                .expect("configure fixture read timeout");
        }
        let (command_tx, command_rx) = mpsc::channel();
        let (event_tx, event_rx) = mpsc::channel();
        let actor = thread::spawn(move || gateway_actor(&mut socket, &command_rx, event_tx));
        command_tx
            .send(GatewayCommand::LoadProjectList {
                request_id: "project-list-1".into(),
                profile: "fixture-profile".into(),
            })
            .and_then(|()| {
                command_tx.send(GatewayCommand::LoadProjectList {
                    request_id: "project-list-2".into(),
                    profile: "fixture-profile".into(),
                })
            })
            .expect("queue projects.list reads");
        assert!(matches!(
            event_rx.recv_timeout(Duration::from_secs(3)).expect("projects.list result"),
            GatewayEvent::ProjectListLoaded {
                request_id,
                profile,
                result: Ok(snapshot),
            } if request_id == "project-list-1"
                && profile == "fixture-profile"
                && snapshot.active_id.as_deref() == Some("p_demo")
                && snapshot.projects[0].name == "Demo"
        ));
        assert!(matches!(
            event_rx.recv_timeout(Duration::from_secs(3)).expect("second projects.list result"),
            GatewayEvent::ProjectListLoaded {
                request_id,
                profile,
                result: Ok(snapshot),
            } if request_id == "project-list-2"
                && profile == "fixture-profile"
                && snapshot.active_id.as_deref() == Some("p_second")
                && snapshot.projects[0].name == "Second"
        ));
        drop(command_tx);
        actor.join().expect("gateway actor exits after peer close");
        server.join().expect("fixture server exits");
    }

