    #[test]
    fn archived_session_pages_dedupe_pinned_backfills_and_use_fixed_offsets() {
        let mut offsets = Vec::new();
        let sessions = collect_archived_session_pages(|offset| {
            offsets.push(offset);
            let rows = if offset == 0 {
                vec![
                    SessionSummary {
                        cwd: None,
                        id: "archived-1".into(),
                        connection_id: None,
                        lineage_root_id: None,
                        profile: Some("alpha".into()),
                        title: "Older conversation".into(),
                        preview: String::new(),
                        message_count: 3,
                        source: "desktop".into(),
                        started_at: 1.0,
                        last_active: None,
                        pinned: false,
                        unread: false,
                        archived: true,
                    },
                    SessionSummary {
                        cwd: None,
                        id: "live-pin".into(),
                        connection_id: None,
                        lineage_root_id: None,
                        profile: Some("alpha".into()),
                        title: "Pinned live row".into(),
                        preview: String::new(),
                        message_count: 1,
                        source: "desktop".into(),
                        started_at: 2.0,
                        last_active: None,
                        pinned: true,
                        unread: false,
                        archived: false,
                    },
                ]
            } else {
                vec![
                    SessionSummary {
                        cwd: None,
                        id: "archived-2".into(),
                        connection_id: None,
                        lineage_root_id: None,
                        profile: Some("beta".into()),
                        title: "Newest archived conversation".into(),
                        preview: String::new(),
                        message_count: 4,
                        source: "desktop".into(),
                        started_at: 3.0,
                        last_active: None,
                        pinned: false,
                        unread: true,
                        archived: true,
                    },
                    SessionSummary {
                        cwd: None,
                        id: "live-pin".into(),
                        connection_id: None,
                        lineage_root_id: None,
                        profile: Some("alpha".into()),
                        title: "Pinned live row".into(),
                        preview: String::new(),
                        message_count: 1,
                        source: "desktop".into(),
                        started_at: 2.0,
                        last_active: None,
                        pinned: true,
                        unread: false,
                        archived: false,
                    },
                    SessionSummary {
                        cwd: None,
                        id: "archived-1".into(),
                        connection_id: None,
                        lineage_root_id: None,
                        profile: Some("beta".into()),
                        title: "Same stored ID in another profile".into(),
                        preview: String::new(),
                        message_count: 2,
                        source: "desktop".into(),
                        started_at: 4.0,
                        last_active: None,
                        pinned: false,
                        unread: false,
                        archived: true,
                    },
                ]
            };
            Ok(SessionListPage {
                sessions: rows,
                total: 3,
            })
        })
        .expect("read every archived page");

        assert_eq!(offsets, [0, 500]);
        assert_eq!(
            sessions
                .iter()
                .map(|session| session.id.as_str())
                .collect::<Vec<_>>(),
            ["archived-1", "live-pin", "archived-2", "archived-1"]
        );
        assert_eq!(
            sessions
                .iter()
                .filter(|session| session.id == "archived-1")
                .map(|session| session.profile.as_deref())
                .collect::<Vec<_>>(),
            [Some("alpha"), Some("beta")]
        );
    }

