    #[test]
    fn fallback_providers_reads_legacy_routes_and_preserves_unknown_fields() {
        let routes = fallback_providers_from_config(&json!({
            "fallback_providers": [
                "openai/gpt-fixture",
                {"provider":"custom","model":"glm-fixture","base_url":"http://gw:8080/v1","key_env":"GW_KEY","api_mode":"responses"}
            ]
        }))
        .expect("valid fallback route config");
        assert_eq!(
            routes[0],
            json!({"provider":"openai","model":"gpt-fixture"})
        );
        assert_eq!(routes[1]["base_url"], "http://gw:8080/v1");
        assert_eq!(routes[1]["key_env"], "GW_KEY");
        assert_eq!(routes[1]["api_mode"], "responses");
        assert!(
            fallback_providers_from_config(&json!({}))
                .unwrap()
                .is_empty()
        );
        assert!(fallback_providers_from_config(&json!({"fallback_providers":["bad"]})).is_err());
        assert!(
            fallback_providers_from_config(&json!({
                "fallback_providers":[{"provider":"openai","model":7}]
            }))
            .is_err()
        );
    }

    #[test]
    fn redact_secrets_config_defaults_on_and_validates_the_profile_value() {
        assert!(redact_secrets_from_config(&json!({})).expect("default redaction setting"));
        assert!(
            redact_secrets_from_config(&json!({"security":{}}))
                .expect("missing value uses secure default")
        );
        assert!(
            redact_secrets_from_config(&json!({"security":{"redact_secrets":true}}))
                .expect("redaction enabled")
        );
        assert!(
            !redact_secrets_from_config(&json!({"security":{"redact_secrets":false}}))
                .expect("explicit profile opt-out")
        );
        assert!(
            redact_secrets_from_config(&json!({"security":{"redact_secrets":"false"}})).is_err()
        );
        assert!(redact_secrets_from_config(&json!({"security":false})).is_err());
        assert_eq!(
            redact_secrets_config_patch(false),
            json!({"config":{"security":{"redact_secrets":false}}})
        );
    }

