    #[test]
    fn rpc_preserves_gateway_busy_code_for_bounded_prompt_recovery() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind fixture gateway");
        let address = listener.local_addr().expect("fixture address");
        let server = thread::spawn(move || {
            let (stream, _) = listener.accept().expect("accept fixture client");
            let mut socket = tungstenite::accept(stream).expect("accept WebSocket");
            let request: serde_json::Value = match socket.read().expect("read request") {
                Message::Text(text) => serde_json::from_str(&text).expect("parse request"),
                other => panic!("expected text request, got {other:?}"),
            };
            assert_eq!(request["jsonrpc"], "2.0");
            assert_eq!(request["method"], "prompt.submit");
            assert_eq!(request["params"]["session_id"], "runtime-1");
            let id = request["id"].as_u64().expect("JSON-RPC request id");
            let refusal = json!({"jsonrpc":"2.0","id":id,"error":{
                "code":4009,"message":"session busy",
                "data":{"reason":"session busy"}
            }});
            assert_eq!(refusal["jsonrpc"], "2.0");
            assert_eq!(refusal["id"], id);
            socket
                .send(Message::Text(refusal.to_string().into()))
                .expect("send busy refusal");
        });
        let (mut socket, _) =
            tungstenite::connect(format!("ws://{address}/api/ws")).expect("connect fixture client");
        let error = rpc_with_events_timeout(
            &mut socket,
            1,
            "prompt.submit",
            json!({"session_id":"runtime-1"}),
            Duration::from_secs(2),
            None,
        )
        .expect_err("busy Gateway response should remain a refusal");
        assert_eq!(
            error,
            "Hermes prompt.submit refused: session busy (code 4009)"
        );
        server.join().expect("fixture exits");
    }

    #[test]
    fn prompt_submit_keeps_the_runtime_session_scope_and_forwards_stream_events() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind fixture gateway");
        let address = listener.local_addr().expect("fixture address");
        let server = thread::spawn(move || {
            let (stream, _) = listener.accept().expect("accept fixture client");
            let mut socket = tungstenite::accept(stream).expect("accept WebSocket");
            let request: serde_json::Value = match socket.read().expect("read prompt request") {
                Message::Text(text) => serde_json::from_str(&text).expect("parse prompt request"),
                other => panic!("expected text request, got {other:?}"),
            };
            assert_eq!(request["jsonrpc"], "2.0");
            assert_eq!(request["method"], "prompt.submit");
            assert_eq!(
                request["params"],
                json!({"session_id":"runtime-1","submission_id":"submission-1","text":"hello Hermes"})
            );
            let id = request["id"].as_u64().expect("JSON-RPC request id");
            for (kind, payload) in [
                ("message.start", json!({"turn_id":"turn-1"})),
                ("message.delta", json!({"text":"Hello "})),
            ] {
                socket
                    .send(Message::Text(
                        json!({
                            "jsonrpc":"2.0","method":"event",
                            "params":{"type":kind,"session_id":"runtime-1","payload":payload}
                        })
                        .to_string()
                        .into(),
                    ))
                    .expect("send stream event");
            }
            socket
                .send(Message::Text(
                    json!({"jsonrpc":"2.0","id":id,"result":{
                        "admission_id":"admission-1","ref":{"session_id":"runtime-1"},
                        "status":"started","sequence":1,"outcome":null,"authority_epoch":1,
                        "execution_generation":1
                    }})
                    .to_string()
                    .into(),
                ))
                .expect("acknowledge prompt");
            socket.send(Message::Text(json!({
                "jsonrpc":"2.0","method":"event",
                "params":{"type":"message.complete","session_id":"runtime-1","payload":{"admission_id":"admission-1","text":"Hello Hermes!","status":"complete"}}
            }).to_string().into())).expect("send completion");
            socket.close(None).expect("close fixture WebSocket");
        });

        let (mut socket, _) =
            tungstenite::connect(format!("ws://{address}/api/ws")).expect("connect fixture client");
        let (command_tx, command_rx) = mpsc::channel();
        let (event_tx, event_rx) = mpsc::channel();
        let actor = thread::spawn(move || gateway_actor(&mut socket, &command_rx, event_tx));
        command_tx
            .send(GatewayCommand::SubmitPrompt {
                session_id: "runtime-1".into(),
                profile: None,
                submission_id: "submission-1".into(),
                text: "hello Hermes".into(),
                attachments: Vec::new(),
            })
            .expect("queue prompt");

        let mut seen = Vec::new();
        for _ in 0..4 {
            seen.push(
                event_rx
                    .recv_timeout(Duration::from_secs(10))
                    .expect("gateway event"),
            );
        }
        assert!(
            matches!(&seen[0], GatewayEvent::ServerEvent { event, .. } if event["type"] == "message.start")
        );
        assert!(
            matches!(&seen[1], GatewayEvent::ServerEvent { event, .. } if event["type"] == "message.delta")
        );
        assert!(
            matches!(&seen[2], GatewayEvent::PromptSubmitted { session_id, submission_id, result: Ok(PromptSubmitReceipt::Admitted { admission_id, status, .. }) } if session_id == "runtime-1" && submission_id == "submission-1" && admission_id == "admission-1" && status == "started")
        );
        assert!(
            matches!(&seen[3], GatewayEvent::ServerEvent { event, .. } if event["type"] == "message.complete")
        );

        drop(command_tx);
        actor.join().expect("gateway actor exits after peer close");
        server.join().expect("fixture server exits");
    }

    #[test]
    fn session_resume_routes_profile_and_preserves_it_in_transcript() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind fixture gateway");
        let address = listener.local_addr().expect("fixture address");
        let server = thread::spawn(move || {
            let (stream, _) = listener.accept().expect("accept fixture client");
            let mut socket = tungstenite::accept(stream).expect("accept WebSocket");
            let request: serde_json::Value = match socket.read().expect("read resume request") {
                Message::Text(text) => serde_json::from_str(&text).expect("parse resume request"),
                other => panic!("expected resume request, got {other:?}"),
            };
            assert_eq!(request["method"], "session.resume");
            assert_eq!(request["params"]["session_id"], "stored-1");
            assert_eq!(request["params"]["profile"], "work");
            let id = request["id"].as_u64().expect("JSON-RPC request id");
            socket
                .send(Message::Text(
                    json!({"jsonrpc":"2.0","id":id,"result":{
                        "session_id":"runtime-1","stored_session_id":"stored-1",
                        "message_count":1,"messages":[{"role":"assistant","content":"hi"}],
                        "pending_connection":{
                            "op_id":"op-resume","seq":3,"deadline_at":1900000000.0,
                            "timeout_seconds":120.0,
                            "targets":[{"name":"Linear","kind":"mcp","action":"install","state":"pending","required_env":[]}]
                        }
                    }})
                    .to_string()
                    .into(),
                ))
                .expect("send resume snapshot");
            socket.close(None).expect("close fixture socket");
        });

        let (mut socket, _) =
            tungstenite::connect(format!("ws://{address}/api/ws")).expect("connect fixture client");
        let (events, _event_receiver) = mpsc::channel();
        let transcript = resume_session(&mut socket, "stored-1", Some("work".into()), &events)
            .expect("resume scoped session");
        assert_eq!(transcript.session_id, "stored-1");
        assert_eq!(transcript.profile.as_deref(), Some("work"));
        assert_eq!(transcript.runtime_session_id, "runtime-1");
        assert_eq!(transcript.message_count, 1);
        assert_eq!(transcript.messages[0]["content"], "hi");
        assert_eq!(
            transcript.pending_connection.as_ref().unwrap()["op_id"],
            "op-resume"
        );
        server.join().expect("fixture server exits");
    }

    #[test]
    fn session_resume_streams_inflight_events_and_recovers_after_refusal() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind fixture gateway");
        let address = listener.local_addr().expect("fixture address");
        let server = thread::spawn(move || {
            let (stream, _) = listener.accept().expect("accept fixture client");
            let mut socket = tungstenite::accept(stream).expect("accept WebSocket");

            let first: serde_json::Value = match socket.read().expect("read first resume") {
                Message::Text(text) => serde_json::from_str(&text).expect("parse first resume"),
                other => panic!("expected first resume request, got {other:?}"),
            };
            assert_eq!(first["method"], "session.resume");
            assert_eq!(first["params"]["session_id"], "stored-live-1");
            assert_eq!(first["params"]["profile"], "work");
            socket
                .send(Message::Text(
                    json!({
                        "jsonrpc":"2.0", "id":first["id"],
                        "error":{"code":-32000,"message":"temporarily unavailable","data":{"reason":"temporarily_unavailable"}}
                    })
                    .to_string()
                    .into(),
                ))
                .expect("refuse first resume");

            let retry: serde_json::Value = match socket.read().expect("read resume retry") {
                Message::Text(text) => serde_json::from_str(&text).expect("parse resume retry"),
                other => panic!("expected resume retry, got {other:?}"),
            };
            assert_eq!(retry["method"], "session.resume");
            assert_eq!(retry["params"]["session_id"], "stored-live-1");
            assert_eq!(retry["params"]["profile"], "work");
            let retry_id = retry["id"].as_u64().expect("JSON-RPC retry id");

            for (kind, payload) in [
                ("message.start", json!({"turn_id":"turn-live-1"})),
                ("message.delta", json!({"text":"Resumed response"})),
            ] {
                socket
                    .send(Message::Text(
                        json!({
                            "jsonrpc":"2.0", "method":"event",
                            "params":{"type":kind,"session_id":"runtime-live-1","payload":payload}
                        })
                        .to_string()
                        .into(),
                    ))
                    .expect("send in-flight event while resume is pending");
            }
            socket
                .send(Message::Text(
                    json!({
                        "jsonrpc":"2.0", "id":retry_id,
                        "result":{
                            "session_id":"runtime-live-1", "stored_session_id":"stored-live-1",
                            "message_count":2,
                            "messages":[{"role":"assistant","content":"Resumed response"}]
                        }
                    })
                    .to_string()
                    .into(),
                ))
                .expect("return resumed transcript snapshot");
            socket
                .send(Message::Text(
                    json!({
                        "jsonrpc":"2.0", "method":"event",
                        "params":{"type":"message.complete","session_id":"runtime-live-1","payload":{"turn_id":"turn-live-1"}}
                    })
                    .to_string()
                    .into(),
                ))
                .expect("send in-flight completion after resume snapshot");
            socket.close(None).expect("close fixture socket");
        });

        let (mut socket, _) =
            tungstenite::connect(format!("ws://{address}/api/ws")).expect("connect fixture client");
        if let tungstenite::stream::MaybeTlsStream::Plain(stream) = socket.get_mut() {
            stream
                .set_read_timeout(Some(Duration::from_millis(100)))
                .expect("configure client read timeout");
        }
        let (command_tx, command_rx) = mpsc::channel();
        let (event_tx, event_rx) = mpsc::channel();
        let actor = thread::spawn(move || gateway_actor(&mut socket, &command_rx, event_tx));
        command_tx
            .send(GatewayCommand::ResumeSession {
                request_id: "resume-first".into(),
                session_id: "stored-live-1".into(),
                profile: Some("work".into()),
            })
            .expect("queue first resume");
        assert!(matches!(
            event_rx.recv_timeout(Duration::from_secs(3)).expect("resume refusal"),
            GatewayEvent::SessionResumed {
                request_id, session_id, profile, result: Err(error), ..
            } if request_id == "resume-first"
                && session_id == "stored-live-1"
                && profile.as_deref() == Some("work")
                && error.contains("temporarily_unavailable")
        ));

        command_tx
            .send(GatewayCommand::ResumeSession {
                request_id: "resume-retry".into(),
                session_id: "stored-live-1".into(),
                profile: Some("work".into()),
            })
            .expect("queue retry after refusal");
        let mut seen = Vec::new();
        for _ in 0..4 {
            seen.push(
                event_rx
                    .recv_timeout(Duration::from_secs(3))
                    .expect("retry stream or resume event"),
            );
        }
        assert!(matches!(
            &seen[0],
            GatewayEvent::ServerEvent { event, .. } if event["type"] == "message.start"
                && event["session_id"] == "runtime-live-1"
        ));
        assert!(matches!(
            &seen[1],
            GatewayEvent::ServerEvent { event, .. } if event["type"] == "message.delta"
                && event["payload"]["text"] == "Resumed response"
        ));
        assert!(matches!(
            &seen[2],
            GatewayEvent::SessionResumed {
                request_id, session_id, profile,
                result: Ok(transcript), ..
            } if request_id == "resume-retry"
                && session_id == "stored-live-1"
                && profile.as_deref() == Some("work")
                && transcript.runtime_session_id == "runtime-live-1"
                && transcript.message_count == 2
        ));
        assert!(matches!(
            &seen[3],
            GatewayEvent::ServerEvent { event, .. } if event["type"] == "message.complete"
        ));

        drop(command_tx);
        actor.join().expect("gateway actor exits after peer close");
        server.join().expect("fixture server exits");
    }

    #[test]
    fn chat_model_mutation_receipt_accepts_a_correlated_commit() {
        let receipt = parse_chat_policy_receipt(
            json!({"session_id":"runtime-1","operation":"model","model":"m2","provider":"p","revision":8}),
            "runtime-1", "model", 7,
        ).expect("valid commit receipt");
        assert_eq!(receipt.status, "committed");
        assert_eq!(receipt.model.as_deref(), Some("m2"));
        assert_eq!(receipt.provider.as_deref(), Some("p"));
        assert_eq!(receipt.revision, Some(8));
    }

    #[test]
    fn chat_model_mutation_receipt_rejects_stale_or_wrong_owner_receipts() {
        let stale = parse_chat_policy_receipt(
            json!({"session_id":"runtime-1","operation":"reasoning","effort":"high","revision":7}),
            "runtime-1",
            "reasoning",
            7,
        );
        assert_eq!(
            stale.expect_err("stale receipt must fail closed"),
            "Hermes chat mutation receipt did not advance its revision"
        );
        let wrong_session = parse_chat_policy_receipt(
            json!({"session_id":"other","operation":"model","model":"m2","revision":8}),
            "runtime-1",
            "model",
            7,
        );
        assert_eq!(
            wrong_session.expect_err("wrong owner receipt must fail closed"),
            "Hermes chat mutation receipt destination mismatch"
        );
        let wrong_operation = parse_chat_policy_receipt(
            json!({"session_id":"runtime-1","operation":"reasoning","revision":8}),
            "runtime-1",
            "model",
            7,
        );
        assert_eq!(
            wrong_operation.expect_err("wrong operation must fail closed"),
            "Hermes chat mutation receipt operation mismatch"
        );
    }

    #[test]
    fn guarded_chat_model_receipt_requires_confirmation_token() {
        let missing = parse_chat_policy_receipt(
            json!({"session_id":"runtime-1","operation":"model","status":"confirmation_required"}),
            "runtime-1",
            "model",
            7,
        );
        assert_eq!(
            missing.expect_err("guarded receipt must include a token"),
            "Hermes guarded model receipt omitted its confirmation token"
        );
        let guarded = parse_chat_policy_receipt(
            json!({"session_id":"runtime-1","operation":"model","status":"confirmation_required","confirm":"opaque"}),
            "runtime-1", "model", 7,
        ).expect("valid guarded receipt");
        assert_eq!(guarded.confirm.as_deref(), Some("opaque"));
    }

    #[test]
    fn chat_policy_error_receipts_and_unknown_statuses_fail_closed() {
        let wrong_status = parse_chat_policy_receipt(
            json!({"session_id":"runtime-1","operation":"model","status":"refused","revision":7}),
            "runtime-1",
            "model",
            7,
        );
        assert_eq!(
            wrong_status.expect_err("refusal must not be painted as an applied change"),
            "Hermes returned an unsupported chat mutation status: refused"
        );
    }

    #[test]
    fn context_compression_uses_revision_fenced_mutation_and_resumes_transcript() {
        fn read_request<S: io::Read + io::Write>(
            socket: &mut tungstenite::WebSocket<S>,
        ) -> serde_json::Value {
            match socket.read().expect("read request") {
                Message::Text(text) => serde_json::from_str(&text).expect("parse request"),
                other => panic!("expected request, got {other:?}"),
            }
        }
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind fixture gateway");
        let address = listener.local_addr().expect("fixture address");
        let server = thread::spawn(move || {
            let (stream, _) = listener.accept().expect("accept fixture client");
            let mut socket = tungstenite::accept(stream).expect("accept WebSocket");
            let snapshot = read_request(&mut socket);
            assert_eq!(snapshot["id"], 3);
            assert_eq!(snapshot["method"], "session.resume");
            assert_eq!(snapshot["params"]["session_id"], "runtime-1");
            assert_eq!(snapshot["params"]["profile"], "work");
            assert_eq!(snapshot["params"]["omit_messages"], true);
            socket.send(Message::Text(json!({"jsonrpc":"2.0","id":3,"result":{
                "session_id":"runtime-1","stored_session_id":"stored-1","revision":12,"execution_generation":9
            }}).to_string().into())).expect("send snapshot");

            let mutation = read_request(&mut socket);
            assert_eq!(mutation["id"], 4);
            assert_eq!(mutation["method"], "session.mutate");
            assert_eq!(mutation["params"]["session_id"], "runtime-1");
            assert_eq!(mutation["params"]["profile"], "work");
            assert_eq!(mutation["params"]["request_id"], "compress-1");
            assert_eq!(mutation["params"]["expected_revision"], 12);
            assert_eq!(mutation["params"]["expected_generation"], 9);
            assert_eq!(mutation["params"]["operation"], "compress");
            assert_eq!(mutation["params"]["payload"], json!({}));
            socket.send(Message::Text(json!({"jsonrpc":"2.0","id":4,"result":{
                "session_id":"runtime-1","operation":"compress","status":"committed","revision":13
            }}).to_string().into())).expect("send compression receipt");

            let resume = read_request(&mut socket);
            assert_eq!(resume["id"], 5);
            assert_eq!(resume["method"], "session.resume");
            assert_eq!(resume["params"]["omit_messages"], false);
            socket.send(Message::Text(json!({"jsonrpc":"2.0","id":5,"result":{
                "session_id":"runtime-1","stored_session_id":"stored-1","message_count":3,
                "messages":[{"id":1,"role":"user","content":"earlier"},{"id":2,"role":"assistant","content":"summary"},{"id":3,"role":"user","content":"continue"}]
            }}).to_string().into())).expect("send fresh transcript");
        });
        let (mut socket, _) =
            tungstenite::connect(format!("ws://{address}/api/ws")).expect("connect fixture");
        let (events, _) = mpsc::channel();
        let compressed = compress_session_on_socket(
            &mut socket,
            "runtime-1",
            "stored-1",
            Some("work"),
            "compress-1",
            &events,
        )
        .expect("compression and transcript refresh");
        assert_eq!(compressed.status, "committed");
        assert_eq!(compressed.response["revision"], 13);
        assert_eq!(compressed.message_count, Some(3));
        assert_eq!(compressed.messages.as_ref().map(Vec::len), Some(3));
        assert_eq!(SESSION_COMPRESS_TIMEOUT, Duration::from_millis(660_000));
        server.join().expect("fixture server exits");
    }

